use genewars_runtime::{airborne_building_collision::plan_collision,actor_activation::TrigTables,physics_tables::PhysicsTables};use std::io::{Read,Write};fn main(){let root=std::path::PathBuf::from(std::env::args().nth(1).unwrap());let p=root.join("private/integration/game-runtime/physics");let physics=PhysicsTables::from_mapped_bytes(&std::fs::read(p.join("angle.bin")).unwrap(),&std::fs::read(p.join("bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let mut b=Vec::new();std::io::stdin().read_to_end(&mut b).unwrap();let mut output=Vec::new();for c in b.chunks_exact(132){let xy=[i16::from_le_bytes(c[124..126].try_into().unwrap()),i16::from_le_bytes(c[126..128].try_into().unwrap())];let ground=i32::from_le_bytes(c[128..132].try_into().unwrap());let p=plan_collision(c[..124].try_into().unwrap(),xy,ground,&physics,&trig).unwrap();output.extend(p.after);for v in p.impulse{output.extend(v.to_le_bytes());}}std::io::stdout().write_all(&output).unwrap();}